<script setup lang="ts">
import { subscriptionSchema, templateSchema } from '@brightloop/shared'
import type { Row } from '~/utils/resources'
const props=defineProps<{template?:boolean;id?:string}>()
const route=useRoute(),api=useApi()
const {data:plans}=await useFetch<{items:Row[]}>('/api/plans')
const {data:products}=await useFetch<{items:Row[]}>('/api/products',{query:{status:'active'}})
const customerSearch=ref('')
const {data:customers}=await useFetch<{items:Row[]}>('/api/customers/options',{query:{q:customerSearch}})
const state=reactive<Row>({name:'',validityDays:30,customerId:'',planId:'',templateId:null,startDate:new Date().toISOString().slice(0,10),expiryDate:'',paymentTerm:'NET_15',autoRenew:false,notes:'',lines:[{productId:'',variantId:null,quantity:1,unitPrice:''}]})
const busy=ref(false),error=ref('')
if(props.id){const d=await api<Row>(`/subscriptions/${props.id}`);Object.assign(state,d,{startDate:d.startDate.slice(0,10),expiryDate:d.expiryDate?.slice(0,10)||'',lines:d.lines.map((l:Row)=>({...l,unitPrice:l.unitPrice/100}))})}
if(route.query.template){const all=await api<{items:Row[]}>('/templates');const t=all.items.find(t=>t.id===route.query.template);if(t) Object.assign(state,{templateId:t.id,planId:t.planId,paymentTerm:t.paymentTerm,lines:t.lines.map((l:Row)=>({...l,unitPrice:l.unitPrice==null?'':l.unitPrice/100}))})}
function variants(id:string){return (products.value?.items.find(p=>p.id===id)?.variants||[]).map((v:Row)=>({label:`${v.attribute}: ${v.value} (+${money(v.extraPrice)})`,value:v.id}))}
async function save(){busy.value=true;error.value='';try{const body=JSON.parse(JSON.stringify(state));const result=(props.template?templateSchema:subscriptionSchema).safeParse(body);if(!result.success){error.value=result.error.issues.map(i=>`${i.path.join('.')}: ${i.message}`).join('\n');return}const d=await api<Row>(props.template?'/templates':`/subscriptions${props.id?'/'+props.id:''}`,{method:props.id?'PUT':'POST',body});await navigateTo(props.template?'/templates':`/subscriptions/${d.id}`)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><div class="page"><div class="page-head"><div><h1>{{props.id?'Edit': 'Create'}} {{template?'quotation template':'subscription'}}</h1><p>Set the terms. Brightloop handles the recurring details.</p></div><UButton :to="template?'/templates':'/subscriptions'" color="neutral" variant="ghost">Cancel</UButton></div><UCard><form class="space-y-6" @submit.prevent="save"><UAlert v-if="error" color="error" :title="error" class="whitespace-pre-line"/><div class="form-grid"><template v-if="template"><UFormField label="Template name"><UInput v-model="state.name" class="w-full"/></UFormField><UFormField label="Valid for (days)"><UInput v-model="state.validityDays" type="number" class="w-full"/></UFormField></template><template v-else><UFormField label="Find customer"><UInput v-model="customerSearch" placeholder="Search by name or email" class="w-full"/></UFormField><UFormField label="Customer"><USelect v-model="state.customerId" :items="(customers?.items||[]).map(c=>({label:`${c.name} · ${c.email}`,value:c.id}))" class="w-full"/></UFormField><UFormField label="Start date"><UInput v-model="state.startDate" type="date" class="w-full"/></UFormField><UFormField label="Expiry date (optional)"><UInput v-model="state.expiryDate" type="date" class="w-full"/></UFormField></template><UFormField label="Plan"><USelect v-model="state.planId" :items="(plans?.items||[]).filter(p=>p.active).map(p=>({label:`${p.name} · ${p.interval}`,value:p.id}))" class="w-full"/></UFormField><UFormField label="Payment terms"><USelect v-model="state.paymentTerm" :items="['IMMEDIATE','NET_7','NET_15','NET_30']" class="w-full"/></UFormField></div><div class="border-t border-default pt-5"><div class="flex justify-between mb-4"><h2 class="font-semibold">Product lines</h2><UButton variant="soft" size="xs" icon="i-lucide-plus" @click="state.lines.push({productId:'',variantId:null,quantity:1,unitPrice:''})">Add line</UButton></div><div v-for="(line,i) in state.lines" :key="i" class="grid md:grid-cols-5 gap-3 mb-4 bg-elevated/40 p-4 rounded-lg"><UFormField label="Product"><USelect v-model="line.productId" :items="(products?.items||[]).map(p=>({label:p.name,value:p.id}))" class="w-full" @update:model-value="line.variantId=null"/></UFormField><UFormField label="Variant"><USelect v-model="line.variantId" :items="variants(line.productId)" placeholder="None" class="w-full"/></UFormField><UFormField label="Quantity"><UInput v-model="line.quantity" type="number" min="1" class="w-full"/></UFormField><UFormField label="Unit price override (₹)"><UInput v-model="line.unitPrice" type="number" step="any" placeholder="Catalog price" class="w-full"/></UFormField><UButton :disabled="state.lines.length===1" icon="i-lucide-trash-2" color="error" variant="ghost" class="self-end justify-self-end" aria-label="Remove line" @click="state.lines.splice(i,1)"/></div></div><UFormField label="Notes"><UTextarea v-model="state.notes" class="w-full"/></UFormField><USwitch v-if="!template" v-model="state.autoRenew" label="Automatically renew this subscription"/><div class="flex justify-end"><UButton type="submit" :loading="busy">{{props.id?'Save changes':'Create '+(template?'template':'subscription')}}</UButton></div></form></UCard></div></template>
